function renderNestHome(){nestData=loadNest();normalizeNestData();syncTodayToDaily();renderNestLifePanel();renderSharedAlbum();renderPet();const e=dailyEntry(),mood=$("#nestMoodShow"),aiMood=$("#nestAiMoodShow"),toG=$("#nestToGShow"),note=$("#nestNoteShow"),notebook=$("#nestNotebookPreview");if(mood)mood.textContent=e.userMood||"今天感觉怎么样？";const moodIcon=$("#nestMoodIcon");if(moodIcon){const mi=nestMoodOptions.indexOf(e.userMood);moodIcon.textContent=mi>=0?nestMoodIcons[mi]:"○"}const aiMoodIcon=$("#nestAiMoodIcon");if(aiMoodIcon){const mi=nestMoodOptions.indexOf(e.aiMood);aiMoodIcon.textContent=mi>=0?nestMoodIcons[mi]:"○"}if(aiMood)aiMood.textContent=e.aiMood||"今天还没有选择";const aiNoteShow=$("#nestAiMoodNoteShow");if(aiNoteShow){aiNoteShow.textContent=e.aiMoodNote||"";aiNoteShow.classList.remove("hidden")}if(toG)toG.textContent=e.toG||"写点什么留在这里。";if(note)note.textContent=e.note||"今天有什么想留下来？";if(notebook){const latest=(nestData.notebook||[]).slice(-1)[0];notebook.textContent=latest?.content||"想留下来的话，就写在这里。"}const ua=$("#nestUserAvatar"),aa=$("#nestAiAvatar"),un=$("#nestUserName"),an=$("#nestAiName");if(ua)ua.innerHTML=avatarHTML("user");if(aa)aa.innerHTML=avatarHTML("ai");if(un)un.textContent=state.settings.myName||"你";if(an)an.textContent=state.settings.gName||"他";
 const storyPreview=$("#nestStoryPreview");
 if(storyPreview){
   const eps=(state.memoryEpisodes||[]).slice().sort((a,b)=>String(b.date||"").localeCompare(String(a.date||""))).filter((e,i,a)=>e&&e.title&&e.summary&&i<3);
   storyPreview.innerHTML=eps.length?eps.map(e=>`<div class="nestStoryMini"><span class="nestStoryMiniDot"></span><div><small>${escapeHtml(e.date||"")}</small><b>${escapeHtml(storyWithChatNames(e.title||"我们的故事"))}</b><p>${escapeHtml(storyWithChatNames(e.summary||""))}</p></div></div>`).join(""):"<div class=\"nestStoryMiniEmpty\">重要的共同经历，会慢慢留在这里。</div>";
 }
 updateNestClock();applyNestBackground()}
const nestMoodOptions=["开心","难过","平静","期待","疲惫","烦躁","想念","甜甜的"];
const nestMoodIcons=['☀','♡','☁','◌','✦','⌁','◒','☾','◇','≋','!','♡'];

function currentMoodTarget(){return nestData.moodTarget==="ai"?"ai":"user"}
