function setMoodFromRange(target,index,save=true){chooseMood(index)}
function saveMoodPage(){const target=currentMoodTarget(),quickField=target==="ai"?"aiMood":"userMood",noteField=target==="ai"?"aiMoodNote":"userMoodNote",quickValue=target==="ai"?$("#nestAiMoodValue").textContent.trim():$("#nestMoodValue").textContent.trim(),noteValue=target==="ai"?$("#nestAiMood").value.trim():$("#nestMood").value.trim();saveDailyField(nestViewDateKey,quickField,nestMoodOptions.includes(quickValue)?quickValue:"");saveDailyField(nestViewDateKey,noteField,noteValue)}
function renderMoodPage(){normalizeNestData();const target=currentMoodTarget(),userSection=$("#nestUserMoodSection"),aiSection=$("#nestAiMoodSection"),title=$("#nestMoodPageTitle"),e=dailyEntry(nestViewDateKey);if(userSection)userSection.classList.toggle("hidden",target!=="user");if(aiSection)aiSection.classList.toggle("hidden",target!=="ai");if(title)title.textContent=target==="ai"?"他的心情":"我的心情";const dateEl=target==="ai"?$("#nestAiMoodDate"):$("#nestMoodDate");if(dateEl)dateEl.textContent=nestDateLabel(nestViewDateKey);const value=target==="ai"?(e.aiMood||nestData.moods.ai||""):(e.userMood||nestData.moods.user||"");const note=target==="ai"?(e.aiMoodNote||""):(e.userMoodNote||"");if(target==="user"){const out=$("#nestMoodValue");if(out)out.textContent=value||"还没有选择";renderMoodOptions(value,"nestMoodOptions")}else{const out=$("#nestAiMoodValue"),quote=$("#nestAiMoodQuote");if(out)out.textContent=value||"还没有写下";renderMoodOptions(value,"nestAiMoodOptions");if(quote)quote.textContent=note||value||"他今天还没有留下心情。"}const textarea=target==="ai"?$("#nestAiMood"):$("#nestMood");if(textarea)textarea.value=note} 
function renderMoodOptions(value,id="nestMoodOptions"){const box=$("#"+id);if(!box)return;box.innerHTML=nestMoodOptions.map((name,i)=>`<button type="button" class="nestMoodOption${name===value?" selected":""}" data-mood-index="${i}"><span>${nestMoodIcons[i]||"○"}</span><b>${name}</b></button>`).join("")}
