function saveNotePage(){const value=$("#nestNote")?.value.trim()||"";saveDailyField(nestViewDateKey,"note",value);renderNestHome()}
let nestNotebookPageIndex=0;
function notebookItems(){normalizeNestData();return (nestData.notebook||[]).slice().sort((a,b)=>Number(a.createdAt||0)-Number(b.createdAt||0));}
function renderNestNotebook(){
 const box=$("#nestNotebookList"); if(!box)return;
 const items=notebookItems();
 if(!items.length){nestNotebookPageIndex=0;box.innerHTML=`<div class="nestNotebookEmpty"><div class="nestNotebookEmptyIcon">♡</div><b>本子还是空白的</b><small>想留下来的话，就写在这里。</small></div>`;return;}
 nestNotebookPageIndex=Math.max(0,Math.min(nestNotebookPageIndex,items.length-1));
 const x=items[nestNotebookPageIndex], id=escapeHtml(x.id||"");
 box.innerHTML=`<div class="nestBookViewport"><article class="nestNotebookSheet nestBookPage" data-notebook-id="${id}"><div class="nestNotebookMargin"></div><div class="nestNotebookDate">${escapeHtml(x.date||"")}</div><h3>${escapeHtml(x.title||"这一页，留给我们")}</h3><p>${escapeHtml(x.content||"")}</p><div class="nestNotebookActions"><button type="button" data-notebook-action="edit">修改</button><button type="button" data-notebook-action="delete">删除</button></div><span class="nestNotebookPageNo">${String(nestNotebookPageIndex+1).padStart(2,"0")} / ${String(items.length).padStart(2,"0")}</span></article></div><div class="nestBookPager"><button type="button" data-notebook-page="prev" aria-label="上一页">‹</button><span>第 ${nestNotebookPageIndex+1} 页</span><button type="button" data-notebook-page="next" aria-label="下一页">›</button></div>`;
}
function turnNotebookPage(delta){const items=notebookItems();if(!items.length)return;const next=nestNotebookPageIndex+delta;if(next<0||next>=items.length)return;nestNotebookPageIndex=next;renderNestNotebook();requestAnimationFrame(()=>{const page=document.querySelector(".nestBookPage");if(page){page.classList.remove("page-enter-next","page-enter-prev");void page.offsetWidth;page.classList.add(delta>0?"page-enter-next":"page-enter-prev");}})}
function resetNotebookEditor(){const title=$("#nestNotebookTitle"),text=$("#nestNotebookText"),save=$("#nestNotebookSave"),cancel=$("#nestNotebookCancel");if(title)title.value="";if(text)text.value="";if(save){save.textContent="写进本子";save.dataset.editingId=""}if(cancel)cancel.classList.add("hidden")}
function editNotebookPage(id){normalizeNestData();const x=nestData.notebook.find(v=>v.id===id);if(!x)return;const title=$("#nestNotebookTitle"),text=$("#nestNotebookText"),save=$("#nestNotebookSave"),cancel=$("#nestNotebookCancel");if(title)title.value=x.title||"";if(text)text.value=x.content||"";if(save){save.textContent="保存修改";save.dataset.editingId=id}if(cancel)cancel.classList.remove("hidden");text?.focus();document.querySelector(".nestNotebookWrite")?.scrollIntoView({behavior:"smooth",block:"center"})}
function deleteNotebookPage(id){normalizeNestData();const x=nestData.notebook.find(v=>v.id===id);if(!x)return;if(!confirm(`确定删除“${x.title||"这一页"}”吗？`))return;const items=notebookItems(),removedIndex=items.findIndex(v=>v.id===id);nestData.notebook=nestData.notebook.filter(v=>v.id!==id);if(removedIndex>=0&&removedIndex<=nestNotebookPageIndex)nestNotebookPageIndex=Math.max(0,nestNotebookPageIndex-1);saveNestData();renderNestNotebook();renderNestHome();resetNotebookEditor()}
function saveNotebookPage(){
 const content=$("#nestNotebookText")?.value.trim()||""; if(!content){showErr("本子这一页还没有内容。");return;}
 normalizeNestData();const title=($("#nestNotebookTitle")?.value.trim()||"这一页，留给我们").slice(0,60),editingId=$("#nestNotebookSave")?.dataset.editingId||"";
 if(editingId){const x=nestData.notebook.find(v=>v.id===editingId);if(x){x.title=title;x.content=content;x.updatedAt=Date.now();}else{return resetNotebookEditor();}}
 else {nestData.notebook.push({id:crypto.randomUUID(),date:nestDateKey(),title,content,createdAt:Date.now()});nestNotebookPageIndex=Math.max(0,nestData.notebook.length-1);}
 nestData.notebook=nestData.notebook.slice(-80); saveNestData(); renderNestNotebook(); renderNestHome(); resetNotebookEditor();
}
function showNestView(view="home"){document.querySelectorAll("#nest .nestPage").forEach(x=>x.classList.add("hidden"));const id=view==="home"?"nestHome":view==="mood"?"nestMoodPage":view==="toG"?"nestToGPage":view==="note"?"nestNotePage":view==="notebook"?"nestNotebookPage":view==="anniversary"?"nestAnniversaryPage":view==="story"?"nestStoryPage":view==="album"?"nestAlbumPage":view==="pet"?"nestPetPage":"nestSettingsPage";$("#"+id)?.classList.remove("hidden");document.querySelectorAll("#nest .nestBottomNav button").forEach(b=>b.classList.toggle("active",b.dataset.nestView===view));if(view==="mood")renderMoodPage();if(view==="toG"){loadDailyPages();applyNestBackground()}if(view==="note"){loadDailyPages()}if(view==="notebook"){renderNestNotebook();applyNestBackground()}if(view==="anniversary"){renderAnniversaries();loadSelectedAnniversaryForm();applyNestBackground();updateNestClock()}if(view==="story"){renderNestStory();applyNestBackground()}if(view==="album"){renderSharedAlbum();applyNestBackground()}if(view==="pet"){renderPet();applyNestBackground()}if(view==="settings")applyNestBackground()}
