function formatTokens(n){return Number(n||0).toLocaleString("en-US")}
function emptyTokenBucket(){return {prompt:0,completion:0,total:0,requests:0}}
function normalizeTokenStats(){const t=state.settings.tokenStats||emptyTokenBucket();t.prompt=Number(t.prompt||0);t.completion=Number(t.completion||0);t.total=Number(t.total||0);t.requests=Number(t.requests||0);t.byType=t.byType||{};["chat","vision","memory","summary"].forEach(k=>{t.byType[k]=t.byType[k]||emptyTokenBucket()});state.settings.tokenStats=t;return t}
function recordTokenUsage(usage,type="chat"){const u=usage||{};const up=Number(u.prompt_tokens??u.input_tokens??u.promptTokens??0)||0,uc=Number(u.completion_tokens??u.output_tokens??u.completionTokens??0)||0;const rawTotal=Number(u.total_tokens??u.totalTokens??0)||0;const ut=rawTotal||up+uc;if(!(up||uc||ut))return false;const t=normalizeTokenStats();const b=t.byType[type]||(t.byType[type]=emptyTokenBucket());t.prompt+=up;t.completion+=uc;t.total+=ut;t.requests+=1;b.prompt+=up;b.completion+=uc;b.total+=ut;b.requests+=1;state.settings.tokenStats=t;save();renderTokenStats();return true}
function renderTokenStats(){const t=normalizeTokenStats(),p=$("#tokenPrompt"),c=$("#tokenCompletion"),tot=$("#tokenTotal"),req=$("#tokenRequests");if(p)p.textContent=formatTokens(t.prompt);if(c)c.textContent=formatTokens(t.completion);if(tot)tot.textContent=formatTokens(t.total);if(req)req.textContent=formatTokens(t.requests);const labels={chat:"聊天",vision:"视觉",memory:"记忆",summary:"摘要"};Object.entries(labels).forEach(([k,label])=>{const q=$("#tokenType-"+k);if(q){const b=t.byType[k]||emptyTokenBucket();q.textContent=`${label} ${formatTokens(b.total)}`}})}
function resetTokenStats(){if(!confirm("确定清零 Token 统计吗？"))return;state.settings.tokenStats={...emptyTokenBucket(),byType:{chat:emptyTokenBucket(),vision:emptyTokenBucket(),memory:emptyTokenBucket(),summary:emptyTokenBucket()}};save();renderTokenStats()}
