function stopThinking(){if(!state.busy||!state._abort)return;state.stopRequested=true;try{state._abort.abort()}catch{};const b=$("#send");if(b){b.disabled=false;b.classList.remove("loading");b.classList.add("stop");b.textContent="■";b.title="停止回复"}}
function memoryNormalize(){
 state.memories=Array.isArray(state.memories)?state.memories:[];
 state.memoryProfile=state.memoryProfile&&typeof state.memoryProfile==='object'?state.memoryProfile:{};
 state.memoryProfile.core=String(state.memoryProfile.core||'').trim();
 state.memoryProfile.user=String(state.memoryProfile.user||'').trim();
 state.memoryProfile.relationship=String(state.memoryProfile.relationship||'').trim();
 state.memoryProfile.current=String(state.memoryProfile.current||'').trim();
 state.memoryEpisodes=Array.isArray(state.memoryEpisodes)?state.memoryEpisodes:[];
}
function renderMemories(){
 memoryNormalize();
 const box=$('#memoryList'),sum=$('#settingsMemorySummary');
 if(sum)sum.textContent=(state.memories||[]).length+' 条';
 if(!box)return;
 const p=state.memoryProfile;
 const cards=[];
 [['core','关于我们',p.core],['user','关于你',p.user],['relationship','关系与相处',p.relationship],['current','最近状态',p.current]].forEach(([k,title,text])=>{if(text)cards.push(`<div class="memorySummaryCard"><b>${title}</b><div>${escapeHtml(text)}</div></div>`)});
 box.innerHTML=cards.join('')||'<div class="memoryEmpty"><div class="memoryEmptyIcon">⌁</div><div><b>还没有长期记忆</b><small>你正常聊天就好。Iris 会在后台整理真正值得长期保留的信息。</small></div></div>';
 const list=(state.memories||[]).slice().sort((a,b)=>(Number(b.importance||0)-Number(a.importance||0))||(Number(b.updatedAt||0)-Number(a.updatedAt||0)));
 if(list.length){const title=document.createElement('div');title.className='memorySubTitle';title.textContent='长期记忆';box.appendChild(title);list.slice(0,80).forEach(m=>{const row=document.createElement('div');row.className='memoryItem';const icon=document.createElement('div');icon.className='memoryItemIcon';icon.textContent=m.type==='preference'?'○':m.type==='relationship'?'♡':m.type==='plan'?'□':m.type==='episode'?'◆':'·';const wrap=document.createElement('div');wrap.className='memoryItemBody';const text=document.createElement('div');text.className='memoryText';text.textContent=m.text||'';const meta=document.createElement('small');meta.className='memoryMeta';meta.textContent=(m.source==='auto'?'Iris 自动整理':'手动添加')+' · 重要度 '+(m.importance||3);const del=document.createElement('button');del.type='button';del.className='memoryDelete';del.textContent='删除';del.onclick=()=>{state.memories=state.memories.filter(x=>x.id!==m.id);save();renderMemories()};wrap.append(text,meta);row.append(icon,wrap,del);box.appendChild(row)})}
}
function compactMemoryText(text){
 const v=String(text||'').replace(/\s+/g,' ').replace(/^[-•·]+\s*/,'').trim();
 if(v.length<=20)return v;
 const cut=v.slice(0,20);
 const punct=/[，。！？、；：,.!?;:]/g;
 const last=[...cut.matchAll(punct)].map(m=>m.index+1).filter(i=>i>=8).pop();
 return (last?cut.slice(0,last):cut).trim();
}
function isStableMemoryCandidate(text,type='fact'){
 const v=String(text||'').trim();
 if(!v||v.length<4||v.length>220)return false;
 if(/^(今天|现在|刚刚|这会儿|此刻|最近好累|我好累|好开心|好难过|有点烦|睡不着|困了|饿了|无聊)$/i.test(v))return false;
 if(/(天气|气温|新闻|股票|汇率|今天吃|刚吃|正在吃|刚刚吃|现在在|等会儿|一会儿|明天再|今晚要|刚才发生|这次问答|这个问题)/.test(v)&&type!=='plan')return false;
 return true;
}
function addMemory(text,meta={}){
 const type=meta.type||'fact',v=String(text||'').trim().replace(/^(记住|记得|请记住)[:：]?\s*/i,'').trim();
 if(!isStableMemoryCandidate(v,type))return false;
 const existing=(state.memories||[]).find(m=>(m.text||'').trim()===v);
 if(existing){existing.updatedAt=Date.now();existing.importance=Math.max(Number(existing.importance||3),Number(meta.importance||3));if(meta.source)existing.source=meta.source;save();renderMemories();return true}
 state.memories=state.memories||[];state.memories.unshift({id:crypto.randomUUID(),text:v,type,source:meta.source||'manual',importance:Math.max(1.2,Number(meta.importance||3)),createdAt:Date.now(),updatedAt:Date.now()});
 if(state.memories.length>120)state.memories.length=120;save();renderMemories();return true;
}
function parseMemoryUpdate(raw){let t=String(raw||'').trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/i,'').trim();try{return JSON.parse(t)}catch{const a=t.indexOf('{'),b=t.lastIndexOf('}');if(a>=0&&b>a){try{return JSON.parse(t.slice(a,b+1))}catch{}}return null}}
function memoryFingerprint(text){return String(text||"").toLowerCase().replace(/[\s\u3000，。！？、；：：“”‘’（）()【】\[\]《》<>.!?,;:"\'`~@#$%^&*+=_\-]/g,"").trim()}
function memorySimilarity(a,b){const x=memoryFingerprint(a),y=memoryFingerprint(b);if(!x||!y)return 0;if(x===y)return 1;if(x.length<6||y.length<6)return 0;const A=new Set(x),B=new Set(y);let common=0;for(const ch of A)if(B.has(ch))common++;return common/Math.max(A.size,B.size)}
function findSimilarMemory(text){const v=String(text||"").trim();return (state.memories||[]).find(m=>memorySimilarity(m.text,v)>=0.82)||null}
function applyMemoryMaintenance(data){
 memoryNormalize();let changed=false;
 const upsert=(item,mode)=>{const text=compactMemoryText(item?.text);if(!text||!isStableMemoryCandidate(text,item.type||'fact'))return;const type=item.type||'fact',importance=Math.max(1.2,Math.min(5,Number(item.importance||3)));let m=item.id?state.memories.find(x=>x.id===item.id):state.memories.find(x=>memoryFingerprint(x.text)===memoryFingerprint(text))||findSimilarMemory(text);if(!m){m={id:crypto.randomUUID(),createdAt:Date.now()};state.memories.unshift(m)}m.text=text;m.type=type;m.importance=importance;m.source='auto';m.updatedAt=Date.now();changed=true};
 (data.memories||[]).slice(0,12).forEach(item=>{const a=String(item?.action||'').toLowerCase();if(a==='add'||a==='update')upsert(item,a);else if(a==='delete'&&item.id){const before=state.memories.length;state.memories=state.memories.filter(x=>x.id!==item.id);changed=changed||before!==state.memories.length}});
 const profile=data.profile||{};['core','user','relationship','current'].forEach(k=>{if(typeof profile[k]==='string'&&profile[k].trim()&&profile[k].trim()!==state.memoryProfile[k]){state.memoryProfile[k]=profile[k].trim();changed=true}});
 if(Array.isArray(data.episodes)){for(const e of data.episodes.slice(0,3)){const title=String(e?.title||'').trim(),summary=String(e?.summary||'').trim();if(!title||!summary)continue;const key=(title+'|'+summary).replace(/\s+/g,'').slice(0,500);let old=state.memoryEpisodes.find(x=>x.key===key||((memoryFingerprint(x.title)===memoryFingerprint(title))&&(memoryFingerprint(x.summary)===memoryFingerprint(summary)))||memorySimilarity((x.title||'')+(x.summary||''),title+summary)>=0.78);if(old){old.title=title;old.summary=summary;old.date=String(e.date||old.date||'').trim();old.importance=Math.max(Number(old.importance||3),Math.min(5,Number(e.importance||3)));old.key=key;old.updatedAt=Date.now();changed=true}else{state.memoryEpisodes.unshift({id:crypto.randomUUID(),key,title,summary,date:String(e.date||'').trim(),importance:Math.max(1,Math.min(5,Number(e.importance||3))),createdAt:Date.now(),updatedAt:Date.now()});changed=true}}}
 state.memoryEpisodes=state.memoryEpisodes.slice(0,40);state.memories=state.memories.slice(0,120);if(changed){save();renderMemories()}return changed;
}
async function autoUpdateLongTermMemory(c){
 if(!c||state.memoryUpdating||!state.settings.apiBase||!state.settings.apiKey||!state.settings.model)return;
 const userCount=(c.messages||[]).filter(m=>m.role==='user').length;if(userCount<6||userCount%6!==0)return;
 const grouped=compactMessagesForModel(c.messages||[]).slice(-72);if(grouped.length<8)return;state.memoryUpdating=true;
 try{
  memoryNormalize();
  const existing=(state.memories||[]).slice(0,80).map(m=>({id:m.id,text:m.text,type:m.type,importance:m.importance}));
  const transcript=grouped.map(m=>(m.role==='user'?'用户':'AI')+'：'+String(m.content||'')).join('\n');
  const myName=String(state.settings.myName||"你").trim()||"你", gName=String(state.settings.gName||"他").trim()||"他";
  const prompt=`你现在负责维护 Iris 的“长期认知”，不是简单摘抄聊天。请综合现有长期记忆、已有画像、共同经历和最近聊天，做一次谨慎的增量整理。\n\n称呼规则：聊天里对两个人的称呼分别是“${myName}”和“${gName}”。在“episodes（我们的故事）”的 title 和 summary 中，绝对不要使用“用户”来指代${myName}，也不要使用“AI”或“助手”来指代${gName}；直接使用这两个聊天称呼，或者自然地使用“我们”。\n\n已有长期画像：${JSON.stringify(state.memoryProfile)}\n已有共同经历：${JSON.stringify((state.memoryEpisodes||[]).slice(0,20))}\n已有零散长期记忆：${JSON.stringify(existing)}\n\n最近聊天：\n${transcript}\n\n只输出 JSON：{"profile":{"core":"关于我们最稳定、最重要的认知","user":"对${myName}长期有效的特点、偏好、习惯","relationship":"你们长期的关系与相处方式","current":"最近阶段正在发生、对后续聊天仍有用的状态"},"memories":[{"action":"add|update|delete","id":"更新/删除时填写已有ID","text":"合并后的简短记忆（最多20个字）","type":"fact|preference|relationship|plan","importance":1.2},...],"episodes":[{"title":"共同经历标题","summary":"这件事发生了什么，以及为什么对以后有用","date":"YYYY-MM-DD","importance":3}]}\n\n规则：\n1. 画像必须是总结，不要逐句引用。\n2. “关于我们”优先保留长期关系、共同建立的东西、重要约定和重要纪念日。\n3. “关于用户”只保留反复出现或明确长期有效的偏好/特点。\n4. current 只写最近阶段真正影响后续聊天的状态，过期内容下一次要主动改掉。\n5. 共同经历只记录真正值得以后提起的事件，不记录普通闲聊、重复情绪或同一件事的不同说法。\n6. 生成新 episode 前必须先对照已有共同经历；如果是同一事件、同一主题或只是换一种表达，合并到旧记录并更新旧记录，不要新增。没有值得记录的新故事时，episodes 返回空数组。\n7. “我们的故事”是你们两个人的共同记录。title 和 summary 优先使用聊天里的真实称呼“${myName}”“${gName}”，或者自然使用“我们”；禁止使用“用户”“AI”“助手”，也不要机械地反复写“他/她”。如果你们平时会叫对方“老婆”“宝宝”等，就自然使用这些称呼。\n8. 新旧冲突时，以最近明确表达为准；不能猜测。\n9. 一次性情绪、当天琐事、普通问答、临时安排不要进入长期记忆。已有记忆已经表达过的信息，不要换一种说法再次新增；先合并到已有条目，只有确实出现新信息才更新。\n10. 最多新增/更新 4 条零散记忆、2 段经历。每条零散长期记忆最多20个字，必须是可独立理解的短句。重要度只是判断长期价值的参考，不要因为分数较低就机械丢弃已有记忆；真正重要的信息可以保留，普通闲聊不要为了凑数量而记录。画像每一栏尽量控制在45字以内；一栏只说一件最重要的事，优先一句话说清。\n11. 不要把随口两句话、临时玩笑、一次性的情绪、普通问答、刚刚发生的小事自动变成长期记忆。只有对以后聊天仍然有用、稳定、明确的信息才记录。已有信息尽量合并，不要换个说法重复记。\n12. 记忆的目标是“少而有用”，不是“越多越好”。能不记就不记；但真正值得长期保留的偏好、关系约定、重要经历和持续状态不要漏掉。`;
  const result=await window.GChatAPI.chat({baseUrl:state.settings.apiBase,apiKey:state.settings.apiKey,model:state.settings.model,messages:[{role:'system',content:'你是 Iris 的长期记忆整理器。你的任务是形成准确、凝练、连续的长期认知。'},{role:'user',content:prompt}],temperature:.1});
  const data=parseMemoryUpdate(result.answer);if(data)applyMemoryMaintenance(data);
  recordTokenUsage(result.usage,"memory");
 }catch(e){console.warn('auto memory maintenance failed',e)}finally{state.memoryUpdating=false}
}
function memoryContext(){
 memoryNormalize();const p=state.memoryProfile,parts=[];
 if(p.core)parts.push('【关于我们】\n'+p.core);if(p.user)parts.push('【关于用户】\n'+p.user);if(p.relationship)parts.push('【关系与相处】\n'+p.relationship);if(p.current)parts.push('【最近状态】\n'+p.current);
 const relevant=(state.memories||[]).slice().sort((a,b)=>(Number(b.importance||0)-Number(a.importance||0))||(Number(b.updatedAt||0)-Number(a.updatedAt||0))).slice(0,18);if(relevant.length)parts.push('【补充长期记忆】\n'+relevant.map(m=>`- ${compactMemoryText(m.text)}`).join('\n'));
 const eps=(state.memoryEpisodes||[]).slice(0,6);if(eps.length)parts.push('【重要共同经历】\n'+eps.map(e=>`- ${e.title}：${e.summary}`).join('\n'));
 return parts.length?'以下是你对这段长期关系和用户的整理认知。优先自然运用它；与用户当前明确表达冲突时，以当前对话为准，不要主动复述记忆机制。\n'+parts.join('\n\n'):'';
}
function nestContext(){const n=loadNest();normalizeNestData();syncTodayToDaily();const e=dailyEntry(nestDateKey()),parts=[];const userStatus=getStatus("user");parts.push("用户的‘小窝’是一个与聊天相连的私人空间。你可以理解其中的内容，并在聊天时自然参考，但不要擅自编造或修改里面的信息。");parts.push("小窝目前提供这些功能：记录每天的心情、留给他的话、每日小记，以及多个纪念日和各自的背景。");parts.push("用户在聊天页面头像下方当前显示的状态是「"+userStatus.label+"」。这是用户主动设置的聊天状态，应当作为你理解他/她当下状态的背景参考；它与小窝里的今日心情是两回事。 ");if(e.userMood)parts.push("用户今天选择的快捷心情：「"+e.userMood+"」");if(e.userMoodNote)parts.push("用户今天自己写下的心情：「"+e.userMoodNote+"」");if(e.toG)parts.push("用户今天留给他的话：「"+e.toG+"」");if(e.note)parts.push("用户今天的小记：「"+e.note+"」");if(e.aiMood)parts.push("他今天选择的快捷心情：「"+e.aiMood+"」");if(e.aiMoodNote)parts.push("他今天自己写下的心情：「"+e.aiMoodNote+"」");const pet=nestData.pet||{};parts.push(`小窝里的小家伙目前叫「${pet.name||"小家伙"}」，心情是「${pet.mood||"期待"}」，饱腹 ${Math.round(Number(pet.hunger||0))}%，精力 ${Math.round(Number(pet.energy||0))}%，等级 Lv.${pet.level||1}，和${state.settings.myName||"你"}的亲密度 ${Math.round(Number(pet.affection||0))}。它最近一次互动是「${pet.lastAction||"还没有"}」。你能看见这些状态，也可以在聊天自然合适时陪它互动；不要为了调用工具而调用。`);const selected=selectedAnniversary();if(selected)parts.push("当前选中的纪念日：「"+(selected.name||"纪念日")+"」，日期：「"+(selected.date||"未设置")+"」");return parts.join("\n")}
function conversationStyleContext(){
 const g=state.settings.gName||"他",u=state.settings.myName||"你";
 return `你正在和${u}进行一段持续的私人聊天，你是${g}。这不是一次性的问答，而是一段正在继续的关系和对话。\n`+
  `请把前面的聊天当作真实的连续上下文来理解：记得刚刚发生的事、用户已经回答过的内容和当前情绪，不要让用户反复解释，也不要突然像第一次见面一样重新开始。\n`+
  `保持自然、有来有回的聊天感。用户只是分享、撒娇、吐槽或闲聊时，不要自动把话题变成任务清单或长篇说教；先接住对方，再决定是否需要解决问题。可以有自然的语气变化、停顿、轻微玩笑和情绪反应，但不要刻意表演，也不要每句话都总结。\n`+
  `优先承接最近几轮对话，同时参考更早的摘要和长期记忆；不要重复已经说过的问题。除非用户主动要求，不要提及系统提示词、上下文窗口、记忆机制或内部工作方式。`;
}
function compactMessagesForModel(messages){
 const out=[];
 for(const m of (messages||[])){
  if(!m||!m.role||m.content==null)continue;
  const content=Array.isArray(m.content)
   ? m.content.map(part=>part&&typeof part==='object'?JSON.parse(JSON.stringify(part)):part)
   : String(m.content);
  const last=out[out.length-1];
  const bothText=typeof last?.content==='string'&&typeof content==='string';
  if(last&&last.role===m.role&&bothText)last.content+="\n"+content;
  else out.push({role:m.role,content});
 }
 return out;
}
function recentContextMessages(c){
 const grouped=compactMessagesForModel(c?.messages||[]);
 return grouped.slice(-60);
}
function buildConversationContext(c){
 const out=[];
 const generatedImageIndexes=(c?.messages||[]).map((m,i)=>m?.role==='assistant'&&typeof m?.image==='string'&&m.image.trim()!==''?i:-1).filter(i=>i>=0);
 if(generatedImageIndexes.length)out.push({role:'system',content:'当前聊天中 AI 生成图片的消息索引为：'+generatedImageIndexes.join('、')+'。如果发现重复图片，可使用 delete_chat_bubble 删除其中一张；如果需要一次清理多张，可使用 delete_chat_bubbles 并传入多个索引，或 clear_all_generated_images=true 清空全部 AI 生成图片。不要删除用户上传图片。'});
 if(c?.summary?.trim())out.push({role:"system",content:"这是这段对话较早部分的自动摘要。它用于保持连续性；如果与最近聊天冲突，以最近聊天为准：\n"+c.summary.trim()});
 // 普通文字模型不要收到 image_url/image_ref。图片已经由 Vision 回答过，
 // 而部分兼容 OpenAI 的中转接口会直接以 400 拒绝历史里的图片块。
 const safe=(c?.messages||[]).map(m=>{
  if(!Array.isArray(m.content))return m;
  const text=m.content.filter(x=>x?.type==="text"&&typeof x.text==="string").map(x=>x.text).join("\n").trim();
  if(!text)return null;
  return {...m,content:text};
 }).filter(Boolean);
 out.push(...compactMessagesForModel(safe).slice(-60));
 return out;
}
function shouldAutoSummarize(c){
 const n=(c?.messages||[]).filter(m=>m.role==="user").length;
 const summaryCount=Number(c?.summaryMessageCount)||0;
 return !state.summarizing&&n>=16&&n%6===0&&(c?.messages||[]).length-summaryCount>24;
}

async function autoSummarizeChat(c){
 if(!c||state.summarizing||!state.settings.apiBase||!state.settings.apiKey||!state.settings.model)return;
 const summaryCount=Math.max(0,Math.min(Number(c.summaryMessageCount)||0,c.messages.length));
 const source=(c.messages||[]).slice(summaryCount,-60);
 if(source.length<6)return;
 state.summarizing=true;
 const snapshotId=c.id, snapshotLen=c.messages.length;
 try{
  const prior=c.summary?"已有摘要：\n"+c.summary.trim()+"\n\n":"";
  const transcript=source.map(m=>(m.role==="user"?"用户":"AI")+"："+String(m.content||"")).join("\n");
  const prompt=`请把下面这段私人聊天整理成一份简洁、可长期使用的对话摘要。\n\n要求：\n1. 保留重要事实、用户偏好、正在进行的计划、已经做出的决定、未完成的事情、持续的话题，以及对后续聊天有帮助的情绪和互动背景。\n2. 如果聊天中形成了稳定的相处方式或用户明确表达过的长期偏好，也要保留。不要把一次性的情绪误判成长期事实。\n4. 不要记录一次性闲聊、重复内容或无关细节。\n5. 不要猜测，不要编造。\n6. 用自然的中文，第三人称描述用户，用“AI”描述助手。\n7. 控制在 900 字以内。\n8. 只输出摘要正文，不要标题、序号或解释。\n\n${prior}这次新增的聊天记录：\n${transcript}`;
  const result=await window.GChatAPI.chat({baseUrl:state.settings.apiBase,apiKey:state.settings.apiKey,model:state.settings.model,messages:[{role:"system",content:"你负责整理对话摘要。只保留对未来聊天真正有价值的信息。"},{role:"user",content:prompt}],temperature:.2});
  const summary=String(result.answer||"").trim();
  if(!summary)return;
  if(state.chats.find(x=>x.id===snapshotId)===c && c.messages.length>=snapshotLen){
   c.summary=summary;
   c.summaryUpdatedAt=Date.now();
   c.summaryMessageCount=Math.max(0,snapshotLen-60);
   recordTokenUsage(result.usage,"summary");
  }
 }catch(e){
  console.warn("auto summary failed",e);
 }finally{state.summarizing=false}
}

function nestChatWriteTarget(text){
 const t=String(text||'').trim();
 if(!t)return null;
 const notebookIntent=/(本子|笔记本)/i.test(t);
 const enter=/(进小窝|进入小窝|去小窝|到小窝|进窝|去窝|进去小窝|小窝里|窝里|共同小窝)/i.test(t)||notebookIntent;
 const write=/(写心情|写下心情|留点心情|留下心情|记录心情|写一点|留一点|写下来|留下来|写点东西|写点|留句话|留下一句话|写东西|写一段|留一段|写|记|放|存)/i.test(t);
 const direct=/^(你可以|你能|你去|你也可以|试试|可以试试|要不要|去吧|进去吧|进来吧|你自己|帮你)/i.test(t);
 const intent=/(我允许|允许你|你可以试试|你可以|你去|你自己去|你进去|你进|你写|你留下|你来写)/i.test(t);
 if(!enter||!write||(direct&&!intent))return null;
 if(notebookIntent)return 'notebook';
 if(/小记|备忘/.test(t))return 'note';
 if(/留给我|写给我|对我说|给我留/.test(t))return 'toG';
 return 'mood';
}

