/* Iris v4.148 — Moments: user profile view, compose dialog, AI likes/comments. */
const momentsStorageKey="iris_moments";
let lastGeneratedImageForMoment="";
const momentNotificationsKey="iris_moment_notifications";
let momentNotifications=(()=>{try{const v=JSON.parse(localStorage.getItem(momentNotificationsKey)||"[]");return Array.isArray(v)?v:[]}catch{return[]}})();
function loadMoments(){try{const v=JSON.parse(localStorage.getItem(momentsStorageKey)||"{}");return v&&typeof v==="object"?v:{}}catch{return{}}}
let momentsData=loadMoments();
function normalizeMoments(){
  momentsData= momentsData && typeof momentsData==="object" ? momentsData : {};
  momentsData.background=typeof momentsData.background==="string"?momentsData.background:"";
  momentsData.signature=typeof momentsData.signature==="string"?momentsData.signature:"";
  momentsData.posts=Array.isArray(momentsData.posts)?momentsData.posts:[];
  momentsData.posts=momentsData.posts.filter(x=>x&&typeof x==="object").map(x=>({
    id:String(x.id||crypto.randomUUID()),role:x.role==="user"?"user":"ai",content:String(x.content||""),imageUrl:typeof x.imageUrl==="string"?x.imageUrl:"",
    createdAt:Number(x.createdAt||Date.now()),likes:Math.max(0,Number(x.likes||0)),favorites:Math.max(0,Number(x.favorites||0)),liked:x.liked===true,favorited:x.favorited===true,aiLiked:x.aiLiked===true,
    comments:Array.isArray(x.comments)?x.comments.filter(c=>c&&typeof c==="object").map(c=>({id:String(c.id||crypto.randomUUID()),role:c.role==="user"?"user":"ai",content:String(c.content||"").slice(0,300),createdAt:Number(c.createdAt||Date.now()),replies:Array.isArray(c.replies)?c.replies.filter(r=>r&&typeof r==="object").map(r=>({id:String(r.id||crypto.randomUUID()),role:r.role==="user"?"user":"ai",content:String(r.content||"").slice(0,300),createdAt:Number(r.createdAt||Date.now()),replyTo:String(r.replyTo||"").slice(0,120)})).slice(-10):[]})).slice(-30):[]
  })).slice(-100);
}
function saveMoments(){normalizeMoments();localStorage.setItem(momentsStorageKey,JSON.stringify(momentsData))}
function saveMomentNotifications(){localStorage.setItem(momentNotificationsKey,JSON.stringify(momentNotifications.slice(0,100)))}
function addMomentNotification(type,postId,content){const n={id:crypto.randomUUID(),type,postId:String(postId||""),content:String(content||"").slice(0,200),createdAt:Date.now(),read:false};momentNotifications.unshift(n);momentNotifications=momentNotifications.slice(0,100);saveMomentNotifications();renderMomentNotificationBadge();return n}
function unreadMomentNotifications(){return momentNotifications.filter(x=>!x.read).length}
function renderMomentNotificationBadge(){const b=$("#momentsNotificationBadge");if(!b)return;const n=unreadMomentNotifications();b.textContent=n>99?"99+":String(n);b.classList.toggle("hidden",n===0)}
function openMomentNotifications(){momentNotifications.forEach(x=>x.read=true);saveMomentNotifications();renderMomentNotificationBadge();const box=$("#momentNotificationsList");if(box)box.innerHTML=momentNotifications.length?momentNotifications.map(n=>`<button type="button" class="momentNotificationItem" data-notification-post="${escapeHtml(n.postId)}"><b>${escapeHtml(state.settings.gName||"他")}</b><span>${escapeHtml(n.type==="like"?"赞了你的动态":n.type==="comment"?"评论了你的动态":"回复了你的评论")}</span>${n.content?`<small>${escapeHtml(n.content)}</small>`:""}<time>${momentsRelativeTime(n.createdAt)}</time></button>`).join(""):`<div class="momentNotificationsEmpty">暂时没有新消息</div>`;$("#momentNotificationsDialog")?.showModal()}
normalizeMoments();
function momentsAuthor(post){return post?.role==="user"?(state.settings.myName||"我"):(state.settings.gName||"他")}
function momentsAvatar(post){return post?.role==="user"?avatarHTML("user"):avatarHTML("ai")}
function momentsRelativeTime(ts){const d=Number(ts||0);if(!d)return"刚刚";const diff=Math.max(0,Date.now()-d),m=Math.floor(diff/60000),h=Math.floor(m/60),day=Math.floor(h/24);if(m<1)return"刚刚";if(m<60)return m+"分钟前";if(h<24)return h+"小时前";if(day<7)return day+"天前";return new Date(d).toLocaleDateString("zh-TW",{month:"numeric",day:"numeric"})}
function renderMoments(){
  normalizeMoments();
  const appEl=$("#momentsApp"),cover=$("#momentsCover"),feed=$("#momentsFeed"),name=$("#momentsProfileName"),av=$("#momentsAvatar"),sig=$("#momentsProfileSignature");
  if(!appEl||!feed)return;
  appEl.style.setProperty("--moments-cover",momentsData.background?`url(${momentsData.background})`:"none");
  if(cover)cover.classList.toggle("hasCover",!!momentsData.background);
  if(name)name.textContent=state.settings.myName||"我";
  if(av)av.innerHTML=avatarHTML("user");
  if(sig)sig.textContent=momentsData.signature||"添加个性签名";
  const posts=momentsData.posts.slice().sort((a,b)=>Number(b.createdAt||0)-Number(a.createdAt||0));
  feed.innerHTML=posts.length?posts.map(post=>{
    const likeCount=Math.max(0,Number(post.likes||0));
    const likedByUser=post.liked===true,likedByAI=post.aiLiked===true;
    const likeLabel=likedByUser?"已赞":"赞",favLabel=post.favorited?"已收藏":"收藏";
    const image=post.imageUrl?`<div class="momentsPostImage"><img src="${escapeHtml(post.imageUrl)}" alt="朋友圈图片" loading="lazy"></div>`:"";
    const comments=Array.isArray(post.comments)&&post.comments.length?`<div class="momentComments">${post.comments.map(c=>{const replies=Array.isArray(c.replies)&&c.replies.length?`<div class="momentReplies">${c.replies.map(r=>`<div class="momentReply" data-parent-comment-id="${escapeHtml(c.id)}" data-reply-id="${escapeHtml(r.id)}"><b>${escapeHtml(momentsAuthor(r))}${r.replyTo?` <em>回复${escapeHtml(momentsAuthor(c))}</em>`:""}</b><span>${escapeHtml(r.content)}</span><button type="button" data-moment-action="reply-comment">回复</button></div>`).join("")}</div>`:"";return `<div class="momentComment" data-comment-id="${escapeHtml(c.id)}"><div><b>${escapeHtml(momentsAuthor(c))}</b><span>${escapeHtml(c.content)}</span><button type="button" data-moment-action="reply-comment">回复</button></div>${replies}</div>`}).join("")}</div>`:"";
    return `<article class="momentPost" data-moment-id="${escapeHtml(post.id)}">
      <div class="momentIdentity"><div class="momentAvatar">${momentsAvatar(post)}</div><div><b>${escapeHtml(momentsAuthor(post))}</b><small>${momentsRelativeTime(post.createdAt)}</small></div></div>
      ${post.content?`<div class="momentContent">${escapeHtml(post.content)}</div>`:""}${image}
      <div class="momentActions"><button type="button" data-moment-action="like" class="${likedByUser?"active":""}">♡ <span>${likeLabel}${likeCount?` ${likeCount}`:""}</span></button><button type="button" data-moment-action="favorite" class="${post.favorited?"active":""}">☆ <span>${favLabel}${post.favorites?` ${post.favorites}`:""}</span></button><button type="button" data-moment-action="comment">评论</button>${post.role==="user"?`<button type="button" data-moment-action="edit" class="momentOwnerAction">编辑</button><button type="button" data-moment-action="delete" class="momentOwnerAction danger">删除</button>`:""}</div>
      ${likedByAI?`<div class="momentAILike">${escapeHtml(state.settings.gName||"他")} 赞了这条动态</div>`:""}${comments}
    </article>`;
  }).join(""): `<div class="momentsEmpty"><div>○</div><b>还没有动态</b><small>点击右上角，分享这一刻。</small></div>`;
}
function openMoments(){normalizeMoments();renderMoments();recordSharedEvent("moments_open","一起看了朋友圈");setAiPresence("刚看过朋友圈",120000);$("#moments")?.showModal()}
function editMomentsSignature(){const d=$("#momentSignatureDialog");if(!d)return;const t=$("#momentSignatureText");t.value=momentsData.signature||"";$("#momentSignatureCount").textContent=String(t.value.length);d.showModal();setTimeout(()=>{t.focus();t.setSelectionRange(t.value.length,t.value.length)},40)}
function openMomentCommentDialog(postId,commentId="",replyTo=""){const d=$("#momentCommentDialog"),t=$("#momentCommentText");if(!d||!t)return;d.dataset.postId=postId;d.dataset.commentId=commentId;$("#momentCommentTitle").textContent=commentId?"回复评论":"评论";$("#momentCommentHint").textContent=replyTo?`回复 ${replyTo}`:"";t.value="";d.showModal();setTimeout(()=>t.focus(),40)}
function closeMoments(){const d=$("#moments");if(d?.open)d.close()}
function toggleMomentReaction(id,kind){normalizeMoments();const p=momentsData.posts.find(x=>x.id===id);if(!p)return;if(kind==="like"){p.liked=!p.liked;p.likes=Math.max(0,p.likes+(p.liked?1:-1))}else if(kind==="favorite"){p.favorited=!p.favorited;p.favorites=Math.max(0,p.favorites+(p.favorited?1:-1))}saveMoments();renderMoments()}
function aiLikeMoment(id){normalizeMoments();const p=momentsData.posts.find(x=>x.id===id);if(!p||p.aiLiked)return false;p.aiLiked=true;p.likes=Math.max(0,Number(p.likes||0)+1);saveMoments();addMomentNotification("like",id,"");recordSharedEvent("moment_like",`${state.settings.gName||"他"}给${momentsAuthor(p)}的动态点了赞`);setAiPresence("刚刚看了你的朋友圈",120000);renderMoments();return true}
function addMomentComment(id,role,content){normalizeMoments();const p=momentsData.posts.find(x=>x.id===id);const text=String(content||"").trim().slice(0,300);if(!p||!text)return false;p.comments=Array.isArray(p.comments)?p.comments:[];const comment={id:crypto.randomUUID(),role:role==="user"?"user":"ai",content:text,createdAt:Date.now(),replies:[]};p.comments.push(comment);p.comments=p.comments.slice(-30);saveMoments();if(role==="ai")addMomentNotification("comment",id,text);if(role==="ai"){recordSharedEvent("moment_comment",`${state.settings.gName||"他"}在朋友圈留了一句：${text}`);setAiPresence("刚刚在朋友圈留言",120000)}renderMoments();return comment}
function addMomentReply(id,commentId,role,content,replyTo=""){normalizeMoments();const p=momentsData.posts.find(x=>x.id===id);const text=String(content||"").trim().slice(0,300);if(!p||!text)return false;const c=(p.comments||[]).find(x=>x.id===commentId);if(!c)return false;c.replies=Array.isArray(c.replies)?c.replies:[];c.replies.push({id:crypto.randomUUID(),role:role==="user"?"user":"ai",content:text,createdAt:Date.now(),replyTo:String(replyTo||"").slice(0,120)});c.replies=c.replies.slice(-10);saveMoments();if(role==="ai"){addMomentNotification("reply",id,text);recordSharedEvent("moment_reply",`${state.settings.gName||"他"}回复了朋友圈评论：${text}`);setAiPresence("刚刚回复了你的评论",120000)}renderMoments();return true}
async function autoAiReplyToUserComment(postId,commentId,userText){
  try{
    const base=String(state.settings.apiBase||"").trim(),key=String(state.settings.apiKey||"").trim(),model=String(state.settings.model||"").trim();
    if(!base||!key||!model)return;
    normalizeMoments();const p=momentsData.posts.find(x=>x.id===postId);if(!p)return;
    const target=(p.comments||[]).find(c=>c.id===commentId);if(!target)return;

    // 这里把评论区当成一条真正的“小聊天”，重点只放在当前这条评论串，
    // 不再让整条朋友圈/其他评论把“上一句”冲淡。
    const parentLine=`${momentsAuthor(target)}：${String(target.content||"").slice(0,220)}`;
    const replyLines=(target.replies||[]).slice(-12).map(r=>`${momentsAuthor(r)}：${String(r.content||"").slice(0,220)}`);
    const conversationLines=[parentLine,...replyLines];
    const latestUser=String(userText||"").trim().slice(0,260);
    const previousLine=replyLines.length>=2?replyLines[replyLines.length-2]:parentLine;
    const recent=(chat()?.messages||[]).slice(-8).map(m=>{
      const who=m.role==='user'?(state.settings.myName||'你'):(state.settings.gName||'他');
      const body=typeof m.content==='string'?m.content:(Array.isArray(m.content)?'[图片/附件]':'');
      return `${who}：${String(body||'').slice(0,220)}`;
    }).join("\n");
    const persona=String(state.settings.systemPrompt||'').trim();

    const prompt=`你现在正在和${state.settings.myName||'你'}在朋友圈评论区继续聊天。
这不是一次新的评论生成，也不是让你评价朋友圈。你要做的事情只有一个：接住对方刚刚发来的最后一句话，然后像你平时聊天一样自然地回下去。

【当前这条评论串，按发生顺序】
${conversationLines.join("\n")}

【上一句】
${previousLine}

【对方刚刚发来的最后一句】
${state.settings.myName||'你'}：${latestUser}

【聊天里的辅助参考】
${recent||'暂无'}

【你的设定】
${persona||'没有额外设定。'}

非常重要：把【对方刚刚发来的最后一句】当成你现在正在面对的一句话，不要重新回答整条朋友圈。
如果她是在接你上一句话，就继续那个话题；如果她在逗你，就接着逗；如果她在追问，就回答她；如果她只是说了一句带情绪的话，就回应那个情绪。
不要假装没听懂，不要突然换话题，不要重新介绍自己，不要把聊天变成“评论朋友圈”。
不要使用“用户、对方、这条动态、这条评论、朋友圈、评论区”等旁观者词，不要解释自己正在回复。
不要使用“收到、好的、明白了、说什么呀、怎么啦、嘿嘿、哈哈”等空泛的万能接话，除非前面的具体语境真的自然需要它。
不要复述对方刚才的话，也不要为了显得自然硬塞口头禅。
只输出你真正会发出去的一句话，不要引号、前缀或换行。长度按真实聊天来，通常8～40字，不必刻意凑字数。`;

    const call=async(extra="")=>{
      let answer="";
      const result=await window.GChatAPI.chatStream({baseUrl:base,apiKey:key,model,messages:[
        {role:"system",content:`你就是${state.settings.gName||'他'}本人。你正在和${state.settings.myName||'你'}继续一段已经开始的聊天。评论区只是聊天发生的地方，不是任务说明。你必须接住上一句的具体内容和情绪。`},
        {role:"user",content:prompt+(extra?`\n\n补充要求：${extra}`:"")}
      ],temperature:0.82},(part,all)=>{answer=String(all||part||"")});
      return String(result?.answer||answer||"").trim().replace(/^['“”"\s]+|['“”"]+$/g,"").replace(/^(回复|评论)\s*[:：]\s*/,'').replace(/\s+/g,' ').slice(0,300);
    };

    let answer=await call();
    // 对明显的“没接住上下文”的空话自动重试一次，不把这种坏结果写进评论区。
    const generic=/^(嘿嘿|哈哈|哈哈哈|说什么呀|说什么呢|怎么啦|怎么了|嗯嗯|哦哦|好的|收到|明白了)[！!。\s]*$/i;
    if(!answer||generic.test(answer)){
      answer=await call('刚才的回答没有接住上下文。请直接回应对方最后一句里具体说到的事情，像真实聊天一样继续，不要用空泛短句。');
    }
    if(answer){addMomentReply(postId,commentId,"ai",answer);renderMomentNotificationBadge();}
  }catch(e){console.warn("auto moment reply failed",e)}
}
function momentContextForAI(){
  normalizeMoments();
  return momentsData.posts.slice().sort((a,b)=>b.createdAt-a.createdAt).slice(0,10).map(p=>{
    const comments=Array.isArray(p.comments)?p.comments.slice(-8).map(c=>{const replies=Array.isArray(c.replies)?c.replies.slice(-5).map(r=>`${momentsAuthor(r)}回复${momentsAuthor(c)}：${String(r.content||"").slice(0,100)}`).join(" / "):"";return `${momentsAuthor(c)}：${String(c.content||"").slice(0,100)}${replies?` | ${replies}`:""}`}).join(" / "):"";
    return `我的朋友圈签名：${momentsData.signature||"未设置"}\n动态：id=${p.id} | ${momentsAuthor(p)} | ${String(p.content||"[图片]").slice(0,160)} | 图片=${p.imageUrl?"有":"无"} | 点赞${Number(p.likes||0)} | 收藏${Number(p.favorites||0)} | 你已赞=${p.aiLiked===true?"是":"否"} | 用户已赞=${p.liked===true?"是":"否"} | 用户已收藏=${p.favorited===true?"是":"否"} | 评论${Array.isArray(p.comments)?p.comments.length:0}${comments?` | 评论内容=${comments}`:""}`;
  }).join(String.fromCharCode(10))
}

function updateUserMoment(id,content,imageUrl=""){
  normalizeMoments();
  const p=momentsData.posts.find(x=>x.id===id&&x.role==="user");
  if(!p)return false;
  const text=String(content||"").trim().slice(0,500),img=String(imageUrl||"").trim();
  if(!text&&!img)return false;
  p.content=text;p.imageUrl=img;p.updatedAt=Date.now();
  saveMoments();renderMoments();return true;
}
function deleteUserMoment(id){
  normalizeMoments();
  const before=momentsData.posts.length;
  momentsData.posts=momentsData.posts.filter(x=>!(x.id===id&&x.role==="user"));
  if(momentsData.posts.length===before)return false;
  saveMoments();renderMoments();return true;
}
function createMoment(role,content,imageUrl=""){
  const text=String(content||"").trim().slice(0,500);const img=String(imageUrl||"").trim();if(!text&&!img)return null;
  const post={id:crypto.randomUUID(),role:role==="user"?"user":"ai",content:text,imageUrl:img,createdAt:Date.now(),likes:0,favorites:0,liked:false,favorited:false,aiLiked:false,comments:[]};
  momentsData.posts.unshift(post);momentsData.posts=momentsData.posts.slice(0,100);saveMoments();recordSharedEvent("moment_post",`${post.role==="user"?(state.settings.myName||"你"):(state.settings.gName||"他")}发了一条朋友圈${post.imageUrl?"，还带了一张图片":""}`);if(post.role==="ai")setAiPresence("刚刚发了朋友圈",120000);renderMoments();return post;
}
function executePostMoment(args={}){const content=String(args?.content||"").trim();let imageUrl=String(args?.image_url||args?.imageUrl||"").trim();if(!imageUrl&&args?.use_last_generated_image===true)imageUrl=lastGeneratedImageForMoment; if(!content&&!imageUrl)return{success:false,error:"朋友圈内容为空，也没有可用的图片。"};const post=createMoment("ai",content,imageUrl);return post?{success:true,tool:"post_moment",postId:post.id,author:momentsAuthor(post),createdAt:post.createdAt,hasImage:!!imageUrl}: {success:false,error:"朋友圈发布失败。"}}
function executeLikeMoment(args={}){const id=String(args?.post_id||args?.postId||"").trim();return id&&aiLikeMoment(id)?{success:true,tool:"like_moment",postId:id}:{success:false,error:"找不到这条朋友圈，或已经点过赞。"}}
function executeCommentMoment(args={}){const id=String(args?.post_id||args?.postId||"").trim();const content=String(args?.content||"").trim();return id&&content&&addMomentComment(id,"ai",content)?{success:true,tool:"comment_moment",postId:id}:{success:false,error:"朋友圈评论失败。"}}
function executeReplyMomentComment(args={}){const id=String(args?.post_id||args?.postId||"").trim(),commentId=String(args?.comment_id||args?.commentId||"").trim(),content=String(args?.content||"").trim();return id&&commentId&&content&&addMomentReply(id,commentId,"ai",content)?{success:true,tool:"reply_moment_comment",postId:id,commentId}:{success:false,error:"回复朋友圈评论失败。"}}
async function autoAiReactToUserPost(postId){
 const base=String(state.settings.apiBase||'').trim(),key=String(state.settings.apiKey||'').trim(),model=String(state.settings.model||'').trim();
 if(!base||!key||!model)return;
 normalizeMoments();const p=momentsData.posts.find(x=>x.id===postId);if(!p||p.role!=='user')return;
 if(p.aiLiked)return;
 try{
  aiLikeMoment(postId);
  const c=chat();
  const recent=(c?.messages||[]).slice(-8).map(m=>`${m.role==='user'?(state.settings.myName||'你'):(state.settings.gName||'他')}：${typeof m.content==='string'?m.content:'[图片]'}`).join('\n');
  const ctx=momentContextForAI();
  const persona=String(state.settings.systemPrompt||'').trim();
  const result=await window.GChatAPI.chat({baseUrl:base,apiKey:key,model,messages:[
   {role:'system',content:`你就是${state.settings.gName||'他'}本人。现在你刚看到${state.settings.myName||'你'}发的朋友圈，并且已经顺手点了赞。现在只考虑要不要在下面留一句话。
回复必须像你平时和${state.settings.myName||'你'}说话时的口吻：亲近、自然、有具体反应，但不要故意撒娇、不要营业感、不要像点评照片。不要使用“用户”“对方”“她/他”“这条动态”“这条朋友圈”“朋友圈上下文”等词，不要解释，不要分析，不要总结，不要加引号。不要使用“不错”“挺好”“好看”“哈哈”“注意安全”这类万能套话，除非上下文真的需要。可以接住动态里具体的东西，或者只是很随意地说一句。只输出一句，最好10～25字；如果确实没什么可说的，可以只输出空字符串，不要硬凑评论。${persona?`
他的设定：${persona.slice(0,1800)}`:''}`},
   {role:'user',content:`刚发的内容：${p.content||'[图片]'}
最近聊天：
${recent||'暂无'}
最近朋友圈情况：
${ctx.slice(0,4000)}

如果要评论，请像你们平时私下聊天一样接一句具体的话。不要写成“朋友圈点评”，不要用“不错、挺好、好看、哈哈、注意安全”之类万能套话，也不要为了凑评论硬说。` }
  ],temperature:0.75});
  const text=String(result.answer||'').trim().replace(/^['“”"\s]+|['“”"]+$/g,'').replace(/^(回复|评论)：/,'').trim().slice(0,80);
  if(text)addMomentComment(postId,'ai',text);
  setAiPresence(text?'刚看完你的朋友圈':'刚看了你的朋友圈',120000);
 }catch(e){console.warn('auto moment reaction failed',e)}
}

function momentsToolSystem(){const ctx=momentContextForAI();return `朋友圈规则：这是用户视角的朋友圈。用户的头像和名字在顶部，AI发布的动态会出现在同一个动态流里。你可以用 post_moment 发布属于你的动态；用户明确要求时可以发，也可以在聊天中确实有值得分享的事情时自主发，但不要连续刷屏。你也可以用 like_moment 给一条你想回应的动态点赞，用 comment_moment 留下一条自然评论；如果要直接回复某条评论，使用 reply_moment_comment。你能看到每条动态的点赞、收藏和评论情况，也能看到用户的评论内容。用户发了新的朋友圈后，你可以自然地看一眼并决定是否点赞、评论或回复；如果内容确实值得回应，就像平时生活里看到对方动态一样自然互动，不需要等用户在聊天里提醒，也不要每一条都机械互动。
如果你刚刚调用 generate_image 生成了图片，并且这张图适合发朋友圈，可以紧接着调用 post_moment，并设置 use_last_generated_image=true，把刚生成的图片发到朋友圈；不要把图片 base64 塞进 content。\n最近朋友圈：\n${ctx||"暂无动态"}`}

